"""NumPy MNIST 手写数字识别：训练、评估、图片预测和梯度检查。依赖：python -m pip install numpy pillow matplotlib用法（不传参数时默认训练）：    python mnist_mlp.py    python mnist_mlp.py gradcheck    python mnist_mlp.py train    python mnist_mlp.py evaluate    python mnist_mlp.py predict --image digit.png --save-preprocessed outputs/input.png网络是输入层、一个 ReLU 隐藏层、输出层（两层可训练全连接层）。MNIST 压缩文件 MD5 仅用于公开数据文件的完整性校验。"""import argparseimport csvimport gzipimport hashlibimport jsonimport structimport sysimport timeimport urllib.requestfrom pathlib import Pathimport numpy as npfrom PIL import Image, ImageOpsMNIST_FILES = {    "train_images": ("train-images-idx3-ubyte.gz", "f68b3c2dcbeaaa9fbdd348bbdeb94873"),    "train_labels": ("train-labels-idx1-ubyte.gz", "d53e105ee54ea40749a09fcbcd1e9432"),    "test_images": ("t10k-images-idx3-ubyte.gz", "9fb629c4189551a2d022fa330f9573f3"),    "test_labels": ("t10k-labels-idx1-ubyte.gz", "ec29112dd5afa0611ce80d1b7f02629c"),}MIRRORS = [    "https://storage.googleapis.com/cvdf-datasets/mnist/",    "https://ossci-datasets.s3.amazonaws.com/mnist/",]PARAM_NAMES = ("W1", "b1", "W2", "b2")def file_md5(path):    digest = hashlib.md5()    with Path(path).open("rb") as file:        for chunk in iter(lambda: file.read(1024 * 1024), b""):            digest.update(chunk)    return digest.hexdigest()def get_mnist_file(data_dir, key):    name, expected = MNIST_FILES[key]    folder = Path(data_dir)    folder.mkdir(parents=True, exist_ok=True)    path = folder / name    if path.is_file() and file_md5(path) == expected:        return path    if path.exists():        if not path.is_file():            raise ValueError(f"数据文件路径不是普通文件：{path}")        print(f"缓存校验失败，将重新下载：{path}")    temporary = folder / (name + ".part")    errors = []    for base in MIRRORS:        try:            print(f"下载 {base}{name}")            request = urllib.request.Request(                base + name, headers={"User-Agent": "MNIST-NumPy/2.0"}            )            with urllib.request.urlopen(request, timeout=60) as response:                with temporary.open("wb") as output:                    for chunk in iter(lambda: response.read(1024 * 1024), b""):                        output.write(chunk)            if file_md5(temporary) != expected:                raise ValueError("下载文件完整性校验失败")            temporary.replace(path)            return path        except Exception as exc:            errors.append(f"{base}: {exc}")        finally:            temporary.unlink(missing_ok=True)    raise RuntimeError(        "MNIST 下载失败。请检查网络，或手动把原始 .gz 文件放入 "        f"{folder.resolve()}。详情：\n" + "\n".join(errors)    )def read_images(path):    with gzip.open(path, "rb") as file:        raw = file.read()    if len(raw) < 16:        raise ValueError(f"MNIST 图像文件头不完整：{path}")    magic, count, rows, cols = struct.unpack(">IIII", raw[:16])    if (magic != 2051 or count == 0 or (rows, cols) != (28, 28)            or len(raw) != 16 + count * 784):        raise ValueError(f"非法 MNIST 图像文件：{path}")    return (np.frombuffer(raw, dtype=np.uint8, offset=16)            .reshape(count, 784).astype(np.float32) / 255.0)def read_labels(path):    with gzip.open(path, "rb") as file:        raw = file.read()    if len(raw) < 8:        raise ValueError(f"MNIST 标签文件头不完整：{path}")    magic, count = struct.unpack(">II", raw[:8])    if magic != 2049 or count == 0 or len(raw) != count + 8:        raise ValueError(f"非法 MNIST 标签文件：{path}")    labels = np.frombuffer(raw, dtype=np.uint8, offset=8).astype(np.int64)    if np.any(labels > 9):        raise ValueError("标签不在 0～9 范围内")    return labelsdef load_split(data_dir, split):    if split not in ("train", "test"):        raise ValueError("split 必须为 train 或 test")    x = read_images(get_mnist_file(data_dir, split + "_images"))    y = read_labels(get_mnist_file(data_dir, split + "_labels"))    if len(x) != len(y):        raise ValueError("图像数和标签数不一致")    return x, ydef checked_matmul(a, b):    """严格检查矩阵乘法；后端报浮点异常时用非 BLAS 收缩计算重试。    部分 NumPy/macOS 组合可能在 matmul 中报告异常浮点状态。    不直接屏蔽警告：检查操作数，并用独立计算路径重新求值。    真正的溢出或非有限值仍会报错。回退可能比 BLAS 慢。    """    a, b = np.asarray(a), np.asarray(b)    if a.ndim != 2 or b.ndim != 2 or a.shape[1] != b.shape[0]:        raise ValueError(f"矩阵乘法形状不匹配：{a.shape} 和 {b.shape}")    if not np.isfinite(a).all() or not np.isfinite(b).all():        raise FloatingPointError("矩阵乘法输入包含 NaN/Inf")    try:        with np.errstate(over="raise", invalid="raise", divide="raise"):            result = np.matmul(a, b)    except FloatingPointError as original_error:        with np.errstate(over="raise", invalid="raise", divide="raise"):            result = np.einsum("ik,kj->ij", a, b, optimize=False)        if not np.isfinite(result).all():            raise FloatingPointError("矩阵乘法回退结果包含 NaN/Inf") from original_error        if not getattr(checked_matmul, "reported_fallback", False):            print(                f"提示：matmul 报告浮点异常（{original_error}）；"                "已通过独立计算路径重试，结果为有限值。回退可能降低速度。",                file=sys.stderr,            )            checked_matmul.reported_fallback = True    if not np.isfinite(result).all():        raise FloatingPointError("矩阵乘法结果包含 NaN/Inf")    return resultdef check_labels(y, count, classes):    y = np.asarray(y)    if y.shape != (count,) or not np.issubdtype(y.dtype, np.integer):        raise ValueError("标签必须是一维整数数组，且数量与输入一致")    if np.any(y < 0) or np.any(y >= classes):        raise ValueError(f"标签必须处于 0～{classes - 1} 范围内")    return yclass ThreeLayerMLP:    def __init__(self, input_dim=784, hidden=128, classes=10, seed=42):        if min(input_dim, hidden, classes) <= 0:            raise ValueError("网络各层维度必须为正整数")        rng = np.random.default_rng(seed)        self.params = {            "W1": (rng.standard_normal((input_dim, hidden))                   * np.sqrt(2.0 / input_dim)).astype(np.float32),            "b1": np.zeros((1, hidden), dtype=np.float32),            "W2": (rng.standard_normal((hidden, classes))                   * np.sqrt(1.0 / hidden)).astype(np.float32),            "b2": np.zeros((1, classes), dtype=np.float32),        }    def forward(self, x):        p = self.params        x = np.asarray(x, dtype=p["W1"].dtype)        if x.ndim != 2 or x.shape[1] != p["W1"].shape[0] or len(x) == 0:            raise ValueError(f"输入必须为非空的 (N, {p['W1'].shape[0]}) 数组")        if not np.isfinite(x).all():            raise ValueError("输入包含 NaN/Inf")        # 不逐批打印调试信息；保留必要的数值检查。        with np.errstate(over="raise", invalid="raise", divide="raise"):            z1 = checked_matmul(x, p["W1"]) + p["b1"]            a1 = np.maximum(z1, 0)            z2 = checked_matmul(a1, p["W2"]) + p["b2"]            if not np.isfinite(z2).all():                raise FloatingPointError("网络输出包含 NaN/Inf，请检查模型或降低学习率")            shifted = z2 - z2.max(axis=1, keepdims=True)            log_probs = shifted - np.log(np.exp(shifted).sum(axis=1, keepdims=True))            probs = np.exp(log_probs)        return probs, (x, z1, a1, log_probs)    def predict_proba(self, x):        return self.forward(x)[0]    def loss_and_gradients(self, x, y, l2=1e-4):        if not np.isfinite(l2) or l2 < 0:            raise ValueError("l2 必须为有限非负数")        probs, (x, z1, a1, log_probs) = self.forward(x)        batch = len(x)        y = check_labels(y, batch, probs.shape[1])        p = self.params        with np.errstate(over="raise", invalid="raise", divide="raise"):            loss = -log_probs[np.arange(batch), y].mean()            loss += 0.5 * l2 * (np.sum(p["W1"] ** 2) + np.sum(p["W2"] ** 2))            d2 = probs.copy()            d2[np.arange(batch), y] -= 1            d2 /= batch            d1 = checked_matmul(d2, p["W2"].T) * (z1 > 0)            grads = {                "W1": checked_matmul(x.T, d1) + l2 * p["W1"],                "b1": d1.sum(axis=0, keepdims=True),                "W2": checked_matmul(a1.T, d2) + l2 * p["W2"],                "b2": d2.sum(axis=0, keepdims=True),            }        if not np.isfinite(loss) or not all(np.isfinite(g).all() for g in grads.values()):            raise FloatingPointError("训练出现 NaN/Inf，请检查输入或降低学习率")        return float(loss), grads    def save(self, path, metadata):        if not all(np.isfinite(v).all() for v in self.params.values()):            raise ValueError("拒绝保存包含 NaN/Inf 的模型")        path = Path(path)        path.parent.mkdir(parents=True, exist_ok=True)        temporary = path.with_name(path.name + ".tmp")        try:            with temporary.open("wb") as file:                np.savez_compressed(                    file, **self.params,                    metadata=np.array(json.dumps(metadata, ensure_ascii=False, allow_nan=False)),                )            temporary.replace(path)        finally:            temporary.unlink(missing_ok=True)    @classmethod    def load(cls, path):        if not Path(path).is_file():            raise FileNotFoundError(f"找不到模型 {path}，请先运行 train")        with np.load(path, allow_pickle=False) as data:            if not set(PARAM_NAMES).issubset(data.files):                raise ValueError("模型缺少 W1、b1、W2 或 b2")            weights = {}            for name in PARAM_NAMES:                value = data[name]                if not np.issubdtype(value.dtype, np.floating):                    raise ValueError(f"模型参数 {name} 必须是浮点数组")                with np.errstate(over="raise", invalid="raise"):                    weights[name] = value.astype(np.float32)            metadata = {}            if "metadata" in data.files:                metadata = json.loads(str(data["metadata"].item()))                if not isinstance(metadata, dict):                    raise ValueError("模型元数据必须是 JSON 对象")        w1, w2 = weights["W1"], weights["W2"]        if w1.ndim != 2 or w2.ndim != 2:            raise ValueError("模型权重必须是二维矩阵")        if w1.shape[0] != 784 or w1.shape[1] <= 0 or w2.shape != (w1.shape[1], 10):            raise ValueError("模型结构不是 784 -> H -> 10")        if weights["b1"].shape != (1, w1.shape[1]) or weights["b2"].shape != (1, 10):            raise ValueError("模型偏置形状错误")        if not all(np.isfinite(v).all() for v in weights.values()):            raise ValueError("模型包含 NaN/Inf")        model = cls(hidden=w1.shape[1])        model.params = weights        return model, metadataclass Adam:    def __init__(self, params, lr=0.001, beta1=0.9, beta2=0.999, eps=1e-8):        if not np.isfinite(lr) or lr <= 0 or not np.isfinite(eps) or eps <= 0:            raise ValueError("Adam 的 lr 和 eps 必须为有限正数")        if not (0 <= beta1 < 1 and 0 <= beta2 < 1):            raise ValueError("Adam 的 beta1、beta2 必须在 [0, 1) 内")        self.lr, self.beta1, self.beta2, self.eps = lr, beta1, beta2, eps        self.m = {k: np.zeros_like(v) for k, v in params.items()}        self.v = {k: np.zeros_like(v) for k, v in params.items()}        self.t = 0    def step(self, params, grads):        if params.keys() != grads.keys() or params.keys() != self.m.keys():            raise ValueError("Adam 参数与梯度的名称不一致")        for name, value in params.items():            if grads[name].shape != value.shape or not np.isfinite(grads[name]).all():                raise ValueError(f"梯度 {name} 形状错误或包含 NaN/Inf")        self.t += 1        with np.errstate(over="raise", invalid="raise", divide="raise"):            for name, value in params.items():                g = grads[name]                self.m[name] *= self.beta1                self.m[name] += (1 - self.beta1) * g                self.v[name] *= self.beta2                self.v[name] += (1 - self.beta2) * (g * g)                m_hat = self.m[name] / (1 - self.beta1 ** self.t)                v_hat = self.v[name] / (1 - self.beta2 ** self.t)                value -= self.lr * m_hat / (np.sqrt(v_hat) + self.eps)                if not np.isfinite(value).all():                    raise FloatingPointError(f"更新后的参数 {name} 包含 NaN/Inf")def evaluate(model, x, y, batch_size=1024):    x = np.asarray(x)    if x.ndim != 2 or len(x) == 0 or batch_size <= 0:        raise ValueError("评估数据必须是非空二维数组，batch_size 必须为正数")    y = check_labels(y, len(x), model.params["W2"].shape[1])    total_loss, correct = 0.0, 0    predictions = np.empty(len(y), dtype=np.int64)    for start in range(0, len(x), batch_size):        stop = min(start + batch_size, len(x))        xb, yb = x[start:stop], y[start:stop]        probs, cache = model.forward(xb)        # 用 float64 累加，汇报不包含 L2 的纯交叉熵。        total_loss -= float(cache[3][np.arange(len(yb)), yb].sum(dtype=np.float64))        pred = probs.argmax(axis=1)        correct += int(np.sum(pred == yb))        predictions[start:stop] = pred    ce = total_loss / len(x)    if not np.isfinite(ce):        raise FloatingPointError("评估交叉熵包含 NaN/Inf")    return ce, correct / len(x), predictionsdef pyplot():    try:        import matplotlib        matplotlib.use("Agg")        import matplotlib.pyplot as plt    except ImportError as exc:        raise RuntimeError("绘图需要 matplotlib：python -m pip install matplotlib") from exc    return pltdef save_history(history, folder):    if not history:        return    folder = Path(folder)    folder.mkdir(parents=True, exist_ok=True)    with (folder / "history.csv").open("w", newline="", encoding="utf-8") as file:        writer = csv.DictWriter(file, fieldnames=list(history[0]))        writer.writeheader()        writer.writerows(history)    plt = pyplot()    epochs = [row["epoch"] for row in history]    fig, axes = plt.subplots(1, 2, figsize=(10, 4))    try:        for prefix, label in (("train", "Train"), ("val", "Validation")):            axes[0].plot(epochs, [r[prefix + "_ce"] for r in history], label=label)            axes[1].plot(epochs, [r[prefix + "_accuracy"] for r in history], label=label)        axes[0].set_ylabel("Cross entropy (without L2)")        axes[1].set_ylabel("Accuracy")        for ax in axes:            ax.set_xlabel("Epoch")            ax.grid(alpha=0.25)            ax.legend()        fig.tight_layout()        fig.savefig(folder / "training_curves.png", dpi=160)    finally:        plt.close(fig)def report_test(model, data_dir, folder):    x, y = load_split(data_dir, "test")    ce, accuracy, pred = evaluate(model, x, y)    print(f"\n独立测试集：交叉熵={ce:.5f}，准确率={accuracy:.2%}，样本数={len(y)}")    matrix = np.zeros((10, 10), dtype=np.int64)    np.add.at(matrix, (y, pred), 1)    print("类别    Precision    Recall       F1       Support")    per_class = []    for c in range(10):        tp = int(matrix[c, c])        support = int(matrix[c].sum())        precision = tp / max(int(matrix[:, c].sum()), 1)        recall = tp / max(support, 1)        f1 = 2 * precision * recall / max(precision + recall, 1e-12)        per_class.append({"class": c, "precision": precision, "recall": recall,                          "f1": f1, "support": support})        print(f" {c}       {precision:.4f}      {recall:.4f}     {f1:.4f}      {support}")    macro_f1 = float(np.mean([r["f1"] for r in per_class]))    print(f"Macro-F1={macro_f1:.4f}")    folder = Path(folder)    folder.mkdir(parents=True, exist_ok=True)    with (folder / "test_metrics.json").open("w", encoding="utf-8") as file:        json.dump({"cross_entropy": ce, "accuracy": accuracy, "macro_f1": macro_f1,                   "samples": len(y), "per_class": per_class}, file,                  ensure_ascii=False, indent=2, allow_nan=False)    with (folder / "confusion_matrix.csv").open("w", newline="", encoding="utf-8") as file:        writer = csv.writer(file)        writer.writerow(["true/pred"] + list(range(10)))        for i, row in enumerate(matrix):            writer.writerow([i] + row.tolist())    plt = pyplot()    fig, ax = plt.subplots(figsize=(8, 7))    try:        im = ax.imshow(matrix, cmap="Blues")        for i in range(10):            for j in range(10):                ax.text(j, i, str(matrix[i, j]), ha="center", va="center", fontsize=8,                        color="white" if matrix[i, j] > matrix.max() / 2 else "black")        ax.set(xticks=range(10), yticks=range(10), xlabel="Predicted label",               ylabel="True label", title=f"MNIST test accuracy: {accuracy:.2%}")        fig.colorbar(im, ax=ax)        fig.tight_layout()        fig.savefig(folder / "confusion_matrix.png", dpi=160)    finally:        plt.close(fig)    return {"cross_entropy": ce, "accuracy": accuracy, "macro_f1": macro_f1}def train(args):    pyplot()  # 在开始耗时训练前检查绘图依赖。    x_all, y_all = load_split(args.data_dir, "train")    if not 1 <= args.val_size < len(x_all):        raise ValueError("val-size 必须大于 0 且小于训练数据总数")    rng = np.random.default_rng(args.seed)    order = rng.permutation(len(x_all))    val_idx, train_idx = order[:args.val_size], order[args.val_size:]    x_train, y_train = x_all[train_idx], y_all[train_idx]    x_val, y_val = x_all[val_idx], y_all[val_idx]    del x_all, y_all    model = ThreeLayerMLP(hidden=args.hidden, seed=args.seed)    optimizer = Adam(model.params, lr=args.lr)    config = vars(args).copy()    print(f"训练/验证样本数：{len(x_train)}/{len(x_val)}")    print(f"网络：784 -> {args.hidden} -> 10；参数量："          f"{sum(p.size for p in model.params.values())}")    best_ce, best_epoch, stale = float("inf"), 0, 0    history = []    for epoch in range(1, args.epochs + 1):        begin = time.perf_counter()        indices = rng.permutation(len(x_train))        for start in range(0, len(indices), args.batch_size):            batch = indices[start:start + args.batch_size]            _, grads = model.loss_and_gradients(x_train[batch], y_train[batch], args.l2)            optimizer.step(model.params, grads)        train_ce, train_acc, _ = evaluate(model, x_train, y_train)        val_ce, val_acc, _ = evaluate(model, x_val, y_val)        history.append({"epoch": epoch, "train_ce": train_ce, "train_accuracy": train_acc,                        "val_ce": val_ce, "val_accuracy": val_acc})        improved = val_ce < best_ce        if improved:            best_ce, best_epoch, stale = val_ce, epoch, 0            model.save(args.model, {                "format_version": 2, "config": config, "best_epoch": epoch,                "val_ce": val_ce, "val_accuracy": val_acc,                "preprocessing": "MNIST pixels / 255; 784 row-major features",            })        else:            stale += 1        print(f"Epoch {epoch:02d}/{args.epochs} | train CE={train_ce:.4f}, acc={train_acc:.2%} | "              f"val CE={val_ce:.4f}, acc={val_acc:.2%} | "              f"{time.perf_counter() - begin:.1f}s" + (" | 保存最佳模型" if improved else ""))        save_history(history, args.output_dir)        if stale >= args.patience:            print(f"连续 {args.patience} 轮验证交叉熵未改善，提前停止")            break    print(f"最佳轮次：{best_epoch}；模型：{Path(args.model).resolve()}")    # 只在训练结束后访问测试集，使用验证交叉熵最优的模型。    best_model, _ = ThreeLayerMLP.load(args.model)    report_test(best_model, args.data_dir, args.output_dir)def border_pixels(arr):    return np.concatenate((arr[0], arr[-1], arr[:, 0], arr[:, -1]))def preprocess_image(image, invert="auto"):    """单数字：灰度、极性处理、裁边、等比缩放、质心居中、归一化。    auto 根据边缘中位数判断背景；透明区域按白色背景合成。    适合干净纯色背景；不支持多数字、复杂照片或强阴影。    返回 (1, 784) 数组和实际送入网络的 28x28 图像。    """    if invert not in ("auto", "yes", "no"):        raise ValueError("invert 必须为 auto、yes 或 no")    rgba = ImageOps.exif_transpose(image).convert("RGBA")    if min(rgba.size) < 2:        raise ValueError("输入图像的宽高都必须至少为 2 像素")    background = Image.new("RGBA", rgba.size, (255, 255, 255, 255))    gray = Image.alpha_composite(background, rgba).convert("L")    arr = np.asarray(gray, dtype=np.float32)    should_invert = invert == "yes" or (        invert == "auto" and np.median(border_pixels(arr)) > 127    )    if should_invert:        arr = 255.0 - arr    arr = np.maximum(arr - np.median(border_pixels(arr)), 0)    peak = float(arr.max())    if peak < 10:        raise ValueError("未检测到清晰笔画，请写一个数字或检查前景/背景设置")    arr = arr / peak * 255.0    ys, xs = np.nonzero(arr > 40)    if len(xs) < 3:        raise ValueError("有效笔画像素太少")    crop = Image.fromarray(arr[ys.min():ys.max() + 1, xs.min():xs.max() + 1].astype(np.uint8))    scale = 20.0 / max(crop.size)    width = max(1, round(crop.width * scale))    height = max(1, round(crop.height * scale))    crop = crop.resize((width, height), Image.Resampling.LANCZOS)    canvas = Image.new("L", (28, 28), 0)    canvas.paste(crop, ((28 - width) // 2, (28 - height) // 2))    pixels = np.asarray(canvas, dtype=np.float64)    mass = float(pixels.sum())    if mass <= 0 or not np.isfinite(mass):        raise ValueError("缩放后没有有效笔画，请使用更清晰的图片")    yy, xx = np.indices((28, 28))    cx = float((pixels * xx).sum() / mass)    cy = float((pixels * yy).sum() / mass)    dx, dy = int(round(13.5 - cx)), int(round(13.5 - cy))    # 约束平移范围，避免质心偏移导致笔画被裁掉。    bbox = canvas.getbbox()    if bbox is None:        raise ValueError("缩放后没有有效笔画")    left, top, right, bottom = bbox    dx = max(-left, min(dx, 28 - right))    dy = max(-top, min(dy, 28 - bottom))    centered = Image.new("L", (28, 28), 0)    centered.paste(canvas, (dx, dy))    features = np.asarray(centered, dtype=np.float32).reshape(1, 784) / 255.0    return features, centereddef predict_file(args):    model, _ = ThreeLayerMLP.load(args.model)    with Image.open(args.image) as image:        x, processed = preprocess_image(image, args.invert)    probs = model.predict_proba(x)[0]    top = np.argsort(probs)[::-1][:3]    print(f"识别结果：{int(top[0])}")    for i in top:        print(f"  数字 {i}：模型概率 {probs[i]:.2%}")    print("注意：Softmax 概率不是经过校准的可靠性保证；非数字输入也可能得到高概率")    if args.save_preprocessed:        path = Path(args.save_preprocessed)        path.parent.mkdir(parents=True, exist_ok=True)        processed.save(path)        print(f"预处理图像已保存至：{path}")def gradient_check():    """用 float64 和中心有限差分检查全部参数，无需下载数据。"""    rng = np.random.default_rng(7)    model = ThreeLayerMLP(input_dim=4, hidden=5, classes=3, seed=7)    model.params = {k: v.astype(np.float64) for k, v in model.params.items()}    x = rng.normal(size=(6, 4))    y = rng.integers(0, 3, size=6)    eps, l2 = 1e-5, 0.01    for _ in range(100):        z1 = checked_matmul(x, model.params["W1"]) + model.params["b1"]        if np.min(np.abs(z1)) > 1e-3:            break        model.params["b1"] += 0.013    else:        raise RuntimeError("梯度检查未能避开 ReLU 折点")    _, analytic = model.loss_and_gradients(x, y, l2)    passed = True    for name, parameter in model.params.items():        numeric = np.zeros_like(parameter)        for index in np.ndindex(parameter.shape):            original = parameter[index]            try:                parameter[index] = original + eps                plus, _ = model.loss_and_gradients(x, y, l2)                parameter[index] = original - eps                minus, _ = model.loss_and_gradients(x, y, l2)            finally:                parameter[index] = original            numeric[index] = (plus - minus) / (2 * eps)        difference = np.linalg.norm(numeric - analytic[name])        denominator = max(1e-12, np.linalg.norm(numeric) + np.linalg.norm(analytic[name]))        relative_error = difference / denominator        print(f"{name}: 相对 L2 误差 = {relative_error:.3e}")        passed = passed and relative_error < 1e-6    if not passed:        raise AssertionError("梯度检查未通过")    print("梯度检查通过：数值梯度与解析梯度一致")def parse_args():    parser = argparse.ArgumentParser(description="NumPy 三层神经网络手写数字识别")    sub = parser.add_subparsers(dest="command", required=True)    def shared(name, help_text):        p = sub.add_parser(name, help=help_text)        p.add_argument("--model", default="outputs/mnist_mlp.npz", help="模型路径")        return p    p = shared("train", "下载 MNIST、训练、保存最佳模型并测试")    p.add_argument("--data-dir", default="mnist_data")    p.add_argument("--output-dir", default="outputs")    p.add_argument("--hidden", type=int, default=128)    p.add_argument("--epochs", type=int, default=20)    p.add_argument("--batch-size", type=int, default=128)    p.add_argument("--lr", type=float, default=0.001)    p.add_argument("--l2", type=float, default=1e-4)    p.add_argument("--val-size", type=int, default=5000)    p.add_argument("--patience", type=int, default=5)    p.add_argument("--seed", type=int, default=42)    p = shared("evaluate", "加载模型，在独立测试集上评估")    p.add_argument("--data-dir", default="mnist_data")    p.add_argument("--output-dir", default="outputs")    p = shared("predict", "识别本地图片中的单个数字")    p.add_argument("--image", required=True)    p.add_argument("--invert", choices=["auto", "yes", "no"], default="auto",                   help="反色：auto 自动推断；yes 白底黑字；no 黑底白字")    p.add_argument("--save-preprocessed", default="", help="保存实际送入网络的 28x28 图像")    sub.add_parser("gradcheck", help="无需数据，检查手写反向传播梯度")    args = parser.parse_args(sys.argv[1:] if len(sys.argv) > 1 else ["train"])    if args.command == "train":        if min(args.hidden, args.epochs, args.batch_size, args.patience, args.val_size) <= 0:            parser.error("hidden、epochs、batch-size、patience、val-size 必须为正整数")        if not np.isfinite(args.lr) or args.lr <= 0:            parser.error("lr 必须为有限正数")        if not np.isfinite(args.l2) or args.l2 < 0:            parser.error("l2 必须为有限非负数")        if args.seed < 0:            parser.error("seed 必须为非负整数")    return argsdef main():    args = parse_args()    if args.command == "train":        train(args)    elif args.command == "evaluate":        pyplot()        model, metadata = ThreeLayerMLP.load(args.model)        print(f"加载模型：{args.model}；最佳训练轮次：{metadata.get('best_epoch', '未知')}")        report_test(model, args.data_dir, args.output_dir)    elif args.command == "predict":        predict_file(args)    elif args.command == "gradcheck":        gradient_check()if __name__ == "__main__":    try:        main()    except KeyboardInterrupt:        print("\n操作已中断；若已有成功保存的模型，仍可用于预测。", file=sys.stderr)        sys.exit(130)    except Exception as error:        import traceback        print(f"错误：{error}", file=sys.stderr)        print(f"运行环境：Python {sys.version.split()[0]}；NumPy {np.__version__}；{sys.platform}",              file=sys.stderr)        traceback.print_exc()        sys.exit(1)